// ===============================================================
// Tarea 4 - Big Data (UNAD 202016911) - Grupo 108
// Autora: Johana Andrea Mosquera Giraldo
// Caso de uso: red de IPS "SaludRed" (sedes, médicos, pacientes y
// citas médicas con su atención clínica embebida).
// Archivo 1 de 4: creación de la base de datos, colecciones con
// validación, índices y carga de los datos de prueba.
// Se ejecuta en mongosh (o en la pestaña MONGOSH de Compass).
// ===============================================================

// ---------------------------------------------------------------
// 1. BASE DE DATOS
// ---------------------------------------------------------------
use("saludRedIPS");
db.dropDatabase();   // deja la base limpia para que el script se pueda repetir

// ---------------------------------------------------------------
// 2. COLECCIONES CON VALIDACIÓN DE ESQUEMA ($jsonSchema)
// MongoDB no exige esquema, pero validar los campos clave evita
// documentos incompletos o con tipos equivocados.
// ---------------------------------------------------------------
db.createCollection("sedes", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "nombre", "ciudad", "servicios"],
    properties: {
      nombre:           { bsonType: "string" },
      ciudad:           { bsonType: "string" },
      servicios:        { bsonType: "array", minItems: 1, items: { bsonType: "string" } },
      capacidad_diaria: { bsonType: "number", minimum: 1 }
    }
  } }
});

db.createCollection("medicos", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "nombre", "especialidad", "sede_id", "tarifa_consulta"],
    properties: {
      especialidad:    { enum: ["Medicina general", "Pediatría", "Cardiología", "Ginecología", "Dermatología", "Endocrinología"] },
      sede_id:         { bsonType: "string", pattern: "^SED[0-9]{2}$" },
      tarifa_consulta: { bsonType: "number", minimum: 0 }
    }
  } }
});

db.createCollection("pacientes", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "documento", "nombre", "sexo", "fecha_nacimiento", "eps", "regimen"],
    properties: {
      documento:        { bsonType: "object", required: ["tipo", "numero"] },
      sexo:             { enum: ["F", "M"] },
      fecha_nacimiento: { bsonType: "date" },
      regimen:          { enum: ["Contributivo", "Subsidiado"] },
      alergias:         { bsonType: "array" },
      enfermedades_cronicas: { bsonType: "array" }
    }
  } }
});

db.createCollection("citas", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "paciente_id", "medico_id", "sede_id", "fecha", "tipo", "estado", "valor"],
    properties: {
      fecha:        { bsonType: "date" },
      tipo:         { enum: ["Primera vez", "Control", "Telemedicina", "Prioritaria"] },
      estado:       { enum: ["Programada", "Atendida", "Cancelada", "No asistió"] },
      valor:        { bsonType: "number", minimum: 0 },
      calificacion: { bsonType: "number", minimum: 1, maximum: 5 }
    }
  } }
});

// ---------------------------------------------------------------
// 3. ÍNDICES (aceleran los filtros y los $lookup más usados)
// ---------------------------------------------------------------
db.pacientes.createIndex({ "documento.numero": 1 }, { unique: true });
db.pacientes.createIndex({ eps: 1, regimen: 1 });
db.medicos.createIndex({ especialidad: 1, sede_id: 1 });
db.citas.createIndex({ paciente_id: 1, fecha: -1 });
db.citas.createIndex({ medico_id: 1 });
db.citas.createIndex({ estado: 1, fecha: -1 });
db.citas.createIndex({ "diagnostico.cie10": 1 });

